pragma solidity ^0.8.0;

import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IImmutableState} from "../interfaces/IImmutableState.sol";

/// @title Immutable State
/// @notice A collection of immutable state variables, commonly used across multiple contracts
contract ImmutableState is IImmutableState {
    /// @inheritdoc IImmutableState
    IPoolManager public immutable poolManager;

    /// @notice Thrown when the caller is not PoolManager
    error NotPoolManager();

    /// @notice Only allow calls from the PoolManager contract
    modifier onlyPoolManager() {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        _;
    }

    constructor(IPoolManager _poolManager) {
        poolManager = _poolManager;
    }
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.24;

import { SafeTransferLib } from "@solady/utils/SafeTransferLib.sol";
import { Airlock } from "src/Airlock.sol";

/**
 * @notice
 * @param amount Amount of the top-up (in numeraire)
 * @param isToken0 True if the token0 is the asset token
 */
struct TopUpData {
    uint256 amount;
    bool isToken0;
}

/**
 * @notice Emitted when a top-up is made for an asset / numeraire pair
 * @param sender Address of the sender of the top-up
 * @param asset Address of the asset token
 * @param numeraire Address of the numeraire token (address zero for ETH)
 * @param amount Amount of the top-up (in numeraire)
 */
event TopUp(address indexed sender, address indexed asset, address indexed numeraire, uint256 amount);

/**
 * @notice Emitted when the top-ups for an asset / numeraire pair are pulled up by a migrator
 * @param migrator Address of the migrator pulling up the top-ups
 * @param asset Address of the asset token
 * @param numeraire Address of the numeraire token (address zero for ETH)
 * @param recipient Address of the recipient of the top-ups
 * @param amount Amount of the top-ups pulled up (in numeraire)
 */
event PullUp(
    address indexed migrator, address indexed asset, address indexed numeraire, address recipient, uint256 amount
);

/// @notice Thrown when the sender is not allowed to pull up the top-ups
error SenderCannotPullUp();

/// @notice Thrown when the sender is not the Airlock owner
error SenderNotAirlockOwner();

/// @notice Thrown when the ETH amount sent does not match the specified amount
error InvalidETHAmount();

/// @notice Thrown when the asset/numeraire orientation does not match the existing one for this pair
error InconsistentOrientation();

/**
 * @title TopUpDistributor
 * @author Whetstone Research
 * @notice Receives top-ups (in numeraire) for asset / numeraire pairs and transfers the funds to a recipient
 * when the Airlock migration occurs
 * @custom:security-contact security@whetstone.cc
 */
contract TopUpDistributor {
    /// @notice Address of the Airlock contract
    Airlock public immutable AIRLOCK;

    /// @notice Top-ups data, stored by asset / numeraire pair in ascending order (token0 < token1)
    mapping(address token0 => mapping(address token1 => TopUpData)) public topUpOf;

    /// @notice Returns true if a migrator is allowed to pull up the top-ups
    mapping(address migrator => bool) public canPullUp;

    /// @param airlock Address of the Airlock contract
    constructor(address airlock) {
        AIRLOCK = Airlock(payable(airlock));
    }

    /**
     * @notice Enables (or disables) a migrator to pull up the top-ups
     * @param migrator Address of the migrator
     * @param canPull Whether the migrator can pull up the top-ups or not
     */
    function setPullUp(address migrator, bool canPull) external {
        if (msg.sender != AIRLOCK.owner()) revert SenderNotAirlockOwner();
        canPullUp[migrator] = canPull;
    }

    /**
     * @notice Tops up the amount for a given asset / numeraire pair (only the numeraire is accepted)
     * @param asset Address of the asset
     * @param numeraire Address of the numeraire (pass address zero for ETH)
     * @param amount Amount to top up (in numeraire)
     */
    function topUp(address asset, address numeraire, uint256 amount) external payable {
        (address token0, address token1) = asset < numeraire ? (asset, numeraire) : (numeraire, asset);

        TopUpData storage config = topUpOf[token0][token1];
        if (config.amount == 0) {
            config.isToken0 = asset < numeraire;
        } else {
            require(config.isToken0 == (asset < numeraire), InconsistentOrientation());
        }

        if (numeraire == address(0)) {
            require(msg.value == amount, InvalidETHAmount());
        } else {
            require(msg.value == 0, InvalidETHAmount());
            SafeTransferLib.safeTransferFrom(numeraire, msg.sender, address(this), amount);
        }

        config.amount += amount;
        emit TopUp(msg.sender, asset, numeraire, amount);
    }

    /**
     * @notice Pulls up the top-ups for a given asset / numeraire pair and sends them to the recipient
     * @dev Only callable by an approved migrator
     * @param token0 Address of token0
     * @param token1 Address of token1
     * @param recipient Recipient of the top-ups
     */
    function pullUp(address token0, address token1, address recipient) external {
        require(canPullUp[msg.sender], SenderCannotPullUp());

        TopUpData storage config = topUpOf[token0][token1];

        uint256 amountToPullUp = config.amount;
        if (amountToPullUp == 0) return;
        config.amount = 0;

        address numeraire = config.isToken0 ? token1 : token0;

        if (numeraire == address(0)) {
            SafeTransferLib.safeTransferETH(recipient, amountToPullUp);
        } else {
            SafeTransferLib.safeTransfer(numeraire, recipient, amountToPullUp);
        }

        emit PullUp(msg.sender, config.isToken0 ? token0 : token1, numeraire, recipient, amountToPullUp);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {CustomRevert} from "./CustomRevert.sol";

/// @title Safe casting methods
/// @notice Contains methods for safely casting between types
library SafeCast {
    using CustomRevert for bytes4;

    error SafeCastOverflow();

    /// @notice Cast a uint256 to a uint160, revert on overflow
    /// @param x The uint256 to be downcasted
    /// @return y The downcasted integer, now type uint160
    function toUint160(uint256 x) internal pure returns (uint160 y) {
        y = uint160(x);
        if (y != x) SafeCastOverflow.selector.revertWith();
    }

    /// @notice Cast a uint256 to a uint128, revert on overflow
    /// @param x The uint256 to be downcasted
    /// @return y The downcasted integer, now type uint128
    function toUint128(uint256 x) internal pure returns (uint128 y) {
        y = uint128(x);
        if (x != y) SafeCastOverflow.selector.revertWith();
    }

    /// @notice Cast a int128 to a uint128, revert on overflow or underflow
    /// @param x The int128 to be casted
    /// @return y The casted integer, now type uint128
    function toUint128(int128 x) internal pure returns (uint128 y) {
        if (x < 0) SafeCastOverflow.selector.revertWith();
        y = uint128(x);
    }

    /// @notice Cast a int256 to a int128, revert on overflow or underflow
    /// @param x The int256 to be downcasted
    /// @return y The downcasted integer, now type int128
    function toInt128(int256 x) internal pure returns (int128 y) {
        y = int128(x);
        if (y != x) SafeCastOverflow.selector.revertWith();
    }

    /// @notice Cast a uint256 to a int256, revert on overflow
    /// @param x The uint256 to be casted
    /// @return y The casted integer, now type int256
    function toInt256(uint256 x) internal pure returns (int256 y) {
        y = int256(x);
        if (y < 0) SafeCastOverflow.selector.revertWith();
    }

    /// @notice Cast a uint256 to a int128, revert on overflow
    /// @param x The uint256 to be downcasted
    /// @return The downcasted integer, now type int128
    function toInt128(uint256 x) internal pure returns (int128) {
        if (x >= 1 << 127) SafeCastOverflow.selector.revertWith();
        return int128(int256(x));
    }
}

// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

/// @notice Parses bytes returned from hooks and the byte selector used to check return selectors from hooks.
/// @dev parseSelector also is used to parse the expected selector
/// For parsing hook returns, note that all hooks return either bytes4 or (bytes4, 32-byte-delta) or (bytes4, 32-byte-delta, uint24).
library ParseBytes {
    function parseSelector(bytes memory result) internal pure returns (bytes4 selector) {
        // equivalent: (selector,) = abi.decode(result, (bytes4, int256));
        assembly ("memory-safe") {
            selector := mload(add(result, 0x20))
        }
    }

    function parseFee(bytes memory result) internal pure returns (uint24 lpFee) {
        // equivalent: (,, lpFee) = abi.decode(result, (bytes4, int256, uint24));
        assembly ("memory-safe") {
            lpFee := mload(add(result, 0x60))
        }
    }

    function parseReturnDelta(bytes memory result) internal pure returns (int256 hookReturn) {
        // equivalent: (, hookReturnDelta) = abi.decode(result, (bytes4, int256));
        assembly ("memory-safe") {
            hookReturn := mload(add(result, 0x40))
        }
    }
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.13;

import { BalanceDelta, IPoolManager, PoolKey } from "@v4-core/interfaces/IPoolManager.sol";
import { IUnlockCallback } from "@v4-core/interfaces/callback/IUnlockCallback.sol";
import { SafeCast } from "@v4-core/libraries/SafeCast.sol";
import { BalanceDelta, BalanceDeltaLibrary } from "@v4-core/types/BalanceDelta.sol";
import { Currency } from "@v4-core/types/Currency.sol";
import { PoolKey } from "@v4-core/types/PoolKey.sol";
import { Position } from "src/types/Position.sol";

import { ImmutableState } from "@v4-periphery/base/ImmutableState.sol";

/// @dev Possible actions passed through the `unlockCallback` function
enum Actions {
    Mint,
    Burn,
    Collect
}

/// @dev Thrown when the given action in the `unlockCallback` function is invalid
error InvalidCallbackAction(uint8 action);

/**
 * @dev Struct used to pass data via the `unlockCallback` function
 * @param action Action to perform in the callback
 * @param poolKey Key of the Uniswap V4 pool where the action will be performed
 * @param positions Array of positions to update in the callback
 */
struct CallbackData {
    Actions action;
    PoolKey poolKey;
    Position[] positions;
}

/**
 * @title MiniV4Manager
 * @author Whetstone Research
 * @dev Base contract implementing different actions with the Uniswap V4 `PoolManager` and allowing an inheriting
 * child to mint or burn positions and collect fees from them
 * @custom:security-contact security@whetstone.cc
 */
abstract contract MiniV4Manager is ImmutableState, IUnlockCallback {
    using BalanceDeltaLibrary for BalanceDelta;
    using SafeCast for int128;
    using SafeCast for uint128;
    using SafeCast for uint256;

    /// @notice Ensures this contract can receive ETH
    receive() external payable { }

    /// @inheritdoc IUnlockCallback
    function unlockCallback(bytes calldata data) external onlyPoolManager returns (bytes memory) {
        CallbackData memory callbackData = abi.decode(data, (CallbackData));

        Actions action = callbackData.action;

        BalanceDelta balanceDelta;
        BalanceDelta feesAccrued;

        if (action == Actions.Mint) {
            balanceDelta = _handleMint(callbackData.poolKey, callbackData.positions);
        } else if (action == Actions.Burn) {
            (balanceDelta, feesAccrued) = _handleBurn(callbackData.poolKey, callbackData.positions);
        } else if (action == Actions.Collect) {
            (balanceDelta, feesAccrued) = _handleCollect(callbackData.poolKey, callbackData.positions);
        } else {
            revert InvalidCallbackAction(uint8(action));
        }

        _handleSettle(callbackData.poolKey, balanceDelta);
        return abi.encode(balanceDelta, feesAccrued);
    }

    /**
     * @dev Calls the `PoolManager` to mint the given `positions` from the specified `poolKey` pool
     * @param poolKey Key of the Uniswap V4 pool to mint from
     * @param positions Array of `Position` struct to mint
     * @return balanceDelta Balances denominated in `token0` and `token1` retrieved from the minted positions
     */
    function _mint(PoolKey memory poolKey, Position[] memory positions) internal returns (BalanceDelta balanceDelta) {
        bytes memory data = poolManager.unlock(
            abi.encode(CallbackData({ action: Actions.Mint, poolKey: poolKey, positions: positions }))
        );
        (balanceDelta,) = abi.decode(data, (BalanceDelta, BalanceDelta));
    }

    /**
     * @dev Calls the `PoolManager` to burn the given `positions` from the specified `poolKey` pool
     * @param poolKey Key of the Uniswap V4 pool to burn from
     * @param positions Array of `Position` struct to burn
     * @return balanceDelta Balances denominated in `token0` and `token1` retrieved from the burnt positions
     * @return feesAccrued Fees accrued from the burnt positions since last collection (included in `balanceDelta`)
     */
    function _burn(
        PoolKey memory poolKey,
        Position[] memory positions
    ) internal returns (BalanceDelta balanceDelta, BalanceDelta feesAccrued) {
        bytes memory data = poolManager.unlock(
            abi.encode(CallbackData({ action: Actions.Burn, poolKey: poolKey, positions: positions }))
        );
        (balanceDelta, feesAccrued) = abi.decode(data, (BalanceDelta, BalanceDelta));
    }

    /**
     * @dev Calls the `PoolManager` to collect fees earned by the given `positions` in the specified `poolKey` pool
     * @param poolKey Key of the Uniswap V4 pool to collect fees from
     * @param positions Array of `Position` struct
     * @return feesAccrued Fees collected from the given positions, denominated in `token0` and `token1`
     */
    function _collect(PoolKey memory poolKey, Position[] memory positions) internal returns (BalanceDelta feesAccrued) {
        bytes memory data = poolManager.unlock(
            abi.encode(CallbackData({ action: Actions.Collect, poolKey: poolKey, positions: positions }))
        );
        (, feesAccrued) = abi.decode(data, (BalanceDelta, BalanceDelta));
    }

    /**
     * @dev Handles the minting of the positions during the `PoolManager` callback call
     * @param poolKey Key of the Uniswap V4 pool to mint from
     * @param positions Array of `Position` struct to mint
     * @return balanceDelta Current delta of negative balances denominated in `token0` and `token1`
     */
    function _handleMint(
        PoolKey memory poolKey,
        Position[] memory positions
    ) private returns (BalanceDelta balanceDelta) {
        uint256 length = positions.length;

        for (uint256 i; i != length; ++i) {
            Position memory pos = positions[i];
            IPoolManager.ModifyLiquidityParams memory params = IPoolManager.ModifyLiquidityParams({
                tickLower: pos.tickLower,
                tickUpper: pos.tickUpper,
                liquidityDelta: pos.liquidity.toInt256(),
                salt: pos.salt
            });

            (BalanceDelta delta,) = poolManager.modifyLiquidity(poolKey, params, new bytes(0));
            balanceDelta = balanceDelta + delta;
        }
    }

    /**
     * @dev Handles the burning of the positions during the `PoolManager` callback call
     * @param poolKey Key of the Uniswap V4 pool to burn from
     * @param positions Array of `Position` struct to burn
     * @return totalBalanceDelta Current delta of positive balances denominated in `token0` and `token1`
     * @return totalFeesAccrued Fees accrued from the burnt positions since last collection (included in `balanceDelta`)
     */
    function _handleBurn(
        PoolKey memory poolKey,
        Position[] memory positions
    ) private returns (BalanceDelta totalBalanceDelta, BalanceDelta totalFeesAccrued) {
        uint256 length = positions.length;

        for (uint256 i; i != length; ++i) {
            Position memory pos = positions[i];
            IPoolManager.ModifyLiquidityParams memory params = IPoolManager.ModifyLiquidityParams({
                tickLower: pos.tickLower,
                tickUpper: pos.tickUpper,
                liquidityDelta: -int128(pos.liquidity),
                salt: pos.salt
            });

            (BalanceDelta balanceDelta, BalanceDelta feesAccrued) =
                poolManager.modifyLiquidity(poolKey, params, new bytes(0));
            totalBalanceDelta = totalBalanceDelta + balanceDelta;
            totalFeesAccrued = totalFeesAccrued + feesAccrued;
        }
    }

    /**
     * @dev Handles the collection of the fees during the `PoolManager` callback call
     * @param poolKey Key of the Uniswap V4 pool to collect fees from
     * @param positions Array of `Position` struct to collect fees from
     * @return totalBalanceDelta Balance delta denominated in `token0` and `token1` retrieved from the collected fees,
     * it should be equal to the `feesAccrued`, we're still passing them for informative purposes though
     * @return totalFees Total fees collected from the positions
     */
    function _handleCollect(
        PoolKey memory poolKey,
        Position[] memory positions
    ) private returns (BalanceDelta totalBalanceDelta, BalanceDelta totalFees) {
        uint256 length = positions.length;

        for (uint256 i; i != length; ++i) {
            Position memory pos = positions[i];
            IPoolManager.ModifyLiquidityParams memory params = IPoolManager.ModifyLiquidityParams({
                tickLower: pos.tickLower, tickUpper: pos.tickUpper, liquidityDelta: 0, salt: pos.salt
            });

            (BalanceDelta balanceDelta, BalanceDelta feesAccrued) =
                poolManager.modifyLiquidity(poolKey, params, new bytes(0));

            totalBalanceDelta = totalBalanceDelta + balanceDelta;
            totalFees = totalFees + feesAccrued;
        }
    }

    /**
     * @dev Handles the settlement of the balances during the `PoolManager` callback call
     * @param poolKey Key of the Uniswap V4 pool, used to retrieve the currencies
     * @param delta Current balances to settle denominated in `currency0` and `currency1`
     */
    function _handleSettle(PoolKey memory poolKey, BalanceDelta delta) private {
        if (delta.amount0() > 0) {
            poolManager.take(poolKey.currency0, address(this), delta.amount0().toUint128());
        }

        if (delta.amount1() > 0) {
            poolManager.take(poolKey.currency1, address(this), delta.amount1().toUint128());
        }

        if (delta.amount0() < 0) {
            _pay(poolKey.currency0, poolManager, uint256(-int256(delta.amount0())));
        }

        if (delta.amount1() < 0) {
            _pay(poolKey.currency1, poolManager, uint256(-int256(delta.amount1())));
        }
    }

    /**
     * @dev Pays a debt to the `PoolManager` contract, either using native ETH or an arbitrary ERC20 token
     * @param currency Currency to pay, pass address zero for native ETH
     * @param manager Address of the `PoolManager`
     * @param amount Amount to pay
     */
    function _pay(Currency currency, IPoolManager manager, uint256 amount) private {
        manager.sync(currency);

        if (currency.isAddressZero()) {
            manager.settle{ value: amount }();
        } else {
            currency.transfer(address(manager), amount);
            manager.settle();
        }
    }
}

